import {readFile,writeFile,copyFile} from 'node:fs/promises';import {resolve} from 'node:path';
const out=resolve(process.argv[2]||'../integration-build'),evidence=resolve(out,'evidence'),review=resolve(out,'review');
const browser=JSON.parse(await readFile(resolve(out,'browser-checks.json'),'utf8')),boundary=JSON.parse(await readFile(resolve(out,'boundary-checks.json'),'utf8')),ledger=JSON.parse(await readFile(resolve(out,'coverage-ledger.json'),'utf8'));
if(browser.failures.length||boundary.failures.length)throw Error('Do not package failed checks as completed');
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const groups=[...new Set(browser.images.map(x=>x.key))];
const html=`<!doctype html><html lang="ja"><meta charset="utf-8"><title>統合確認・画像と検査結果</title><style>body{font:15px/1.7 system-ui,sans-serif;color:#183751;margin:26px}h1{font-size:26px}.stats{background:#edf5ff;padding:18px;border-radius:12px}table{border-collapse:collapse}td,th{border:1px solid #cedce8;padding:8px 12px}details{border-top:1px solid #ccd8e4;padding:16px 0}summary{cursor:pointer;font-weight:bold}.row{display:flex;flex-wrap:wrap;gap:14px}figure{margin:12px 0;width:320px}img{width:100%;border:1px solid #ccd8e4}a{color:#165cb9}</style><h1>採用部品の統合確認</h1><p>日本語：相談→検索→メニュー。英語：検索→メニュー。採用済み目次・右欄・評価・コンパクト関連記事を最新編集元から組み合わせました。本番未反映。</p><div class="stats">全記事・複数幅＋相談窓口3幅：${browser.results.length}条件。評価隔離：${browser.votes.length}条件。境界・向き・操作干渉：${boundary.checks.length}条件。失敗0。元HTML309件の基準照合、全288記事の本文/SEO/リンク/スクリプト保全を検査。</div><h2>対応範囲</h2><table><tr><th>状態</th><th>件数</th></tr>${Object.entries(ledger.counts).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('')}</table><p>PLC設備設計#1/#2/#3は右欄なし・前後回/相談案内を保持。相談サービスは専用フォーム/構成を変更せず、送信は試験していません。全記事の画面結果は台帳に記録し、公開状態とは区別します。</p><p>既知の英語自己リンク3件（air-breaker-basic、control-panel-cooling-fan-basic、surge-protection-basic）は原文のまま。本文の技術内容の正しさを検証する監査ではありません。実機iOS/Safari・スクリーンリーダーは未検証です。</p><p>Before/After/Diffは意図した部品変更の確認用です。共通化だけの差分ゼロ検証とは分けています。</p>${groups.map(key=>`<details><summary>${esc(key)}</summary><div class="row">${browser.images.filter(i=>i.key===key).map(i=>`<figure><figcaption>${esc(i.part)}</figcaption><a href="${esc(i.file)}"><img loading="lazy" src="${esc(i.file)}"></a></figure>`).join('')}</div></details>`).join('')}</html>`;
await writeFile(resolve(evidence,'index.html'),html);
for(const name of ['browser-checks.json','boundary-checks.json','preservation.json','coverage-ledger.json','coverage-ledger.csv','provenance.json','build.json','risk-checks.json','regeneration-checks.json','link-resource-audit.json','end-independent-checks.json'])await copyFile(resolve(out,name),resolve(evidence,name));
await writeFile(resolve(review,'README.txt'),'統合確認用。公開用ファイルではありません。評価は模擬応答、フォーム送信は遮断しています。現端末の操作URL http://127.0.0.1:8768/ 。変更前は http://127.0.0.1:8769/ 。画像による確認は別の integrated-evidence artifact内index.htmlを開いてください。全288記事とサービス例外1件を収録しています。元画像・元JS等は同じGitHub版のassetsが必要です。\n');
console.log(JSON.stringify({layout:browser.results.length,votes:browser.votes.length,boundaries:boundary.checks.length,images:browser.images.length,ledger:ledger.counts}));
